// Fictional data generated by the app; never publishes a visitor's uploads.
const xlsx = require('xlsx');
module.exports = (req, res) => {
    const profiles = [
        { id: 900000001, name: 'Alex Demo', gpa: 3.8, course: '1114', grade: 'A' },
        { id: 900000002, name: 'Blair Demo', gpa: 1.8, course: '2114', grade: 'C' },
        { id: 900000003, name: 'Casey Demo', gpa: 3.2, course: '2505', grade: 'B' },
    ];
    const rows = req.params.kind === 'progress' ? profiles.map(p => ({
        ID: p.id, name: p.name, admit_term: 202109, term_taken: 202409,
        advisor_last_name: 'Demo', overall_hrs_attempted: 3, overall_gpa: p.gpa,
        subj_expanded: 'CS', crse_numb: p.course, credit_hours: 3, grade: p.grade,
    })) : profiles.map(p => ({
        'STUDENT ID': p.id, 'EMAIL ADDRESS': `student${p.id}@example.invalid`,
        'COMPLETION TERM CODE': 202509, 'ADVISOR NAME': 'Demo, Advisor',
        'PRIMARY MAJOR CODE': 'CS', 'CITIZEN CODE': 'US', 'STUDENT CLASS DESC': 'Senior',
    }));
    const book = xlsx.utils.book_new();
    xlsx.utils.book_append_sheet(book, xlsx.utils.json_to_sheet(rows), 'Demo');
    res.attachment(`demo-${req.params.kind}.xlsx`);
    res.send(xlsx.write(book, { type: 'buffer', bookType: 'xlsx' }));
};
